import { calculateDose, calculateInfusion } from './calculations.mjs';

const $ = (selector) => document.querySelector(selector);
const format = (value) => new Intl.NumberFormat('pt-BR', {
  maximumSignificantDigits: 6,
}).format(value);

function setError(form, message) {
  const error = form.querySelector('[role="alert"]');
  error.textContent = message;
  error.hidden = !message;
  form.querySelector('.result').hidden = true;
}

$('#dose-form').addEventListener('submit', (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  try {
    const result = calculateDose(Object.fromEntries(new FormData(form)));
    setError(form, '');
    $('#dose-result').innerHTML = `
      <p><strong>Dose por administração:</strong> ${format(result.dosePerAdministration)} ${result.amountUnit}</p>
      <p><strong>Volume por administração:</strong> ${format(result.volumePerDoseMl)} mL</p>
      <p><strong>Total em 24 h:</strong> ${format(result.dosePerDay)} ${result.amountUnit}</p>
      <p><strong>Checagem reversa:</strong> ${format(result.reconstructedPerKg)} ${result.doseUnit}</p>
      ${result.capped ? '<p class="warning">O limite informado foi aplicado. Confirme se o tipo de limite corresponde à referência clínica.</p>' : ''}
    `;
    form.querySelector('.result').hidden = false;
  } catch (error) {
    setError(form, error.message);
  }
});

$('#infusion-form').addEventListener('submit', (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  try {
    const result = calculateInfusion(Object.fromEntries(new FormData(form)));
    setError(form, '');
    $('#infusion-result').innerHTML = `
      <p><strong>Concentração calculada:</strong> ${format(result.concentration)} ${result.concentrationUnit}</p>
      <p><strong>Quantidade por hora:</strong> ${format(result.amountPerHour)} ${result.amountUnit}/h</p>
      <p><strong>Quantidade por minuto:</strong> ${format(result.amountPerMinute)} ${result.amountUnit}/min</p>
      <p><strong>Bomba:</strong> ${format(result.pumpRateMlPerHour)} mL/h</p>
      <p><strong>Consumo:</strong> 6 h ${format(result.volumeFor6HoursMl)} mL · 12 h ${format(result.volumeFor12HoursMl)} mL · 24 h ${format(result.volumeFor24HoursMl)} mL</p>
      <p><strong>Duração estimada da solução:</strong> ${format(result.solutionDurationHours)} h</p>
      <p><strong>Checagem reversa:</strong> ${format(result.reconstructedPerKg)} ${result.doseUnit}</p>
    `;
    form.querySelector('.result').hidden = false;
  } catch (error) {
    setError(form, error.message);
  }
});

document.querySelectorAll('[data-daily-field]').forEach((field) => {
  $('#dose-unit').addEventListener('change', (event) => {
    field.hidden = !event.target.value.endsWith('/day');
  });
});

const amountUnits = {
  g: { dimension: 'mass', factor: 1000 },
  mg: { dimension: 'mass', factor: 1 },
  mcg: { dimension: 'mass', factor: 0.001 },
  U: { dimension: 'unit', factor: 1 },
  mU: { dimension: 'unit', factor: 0.001 },
  mEq: { dimension: 'equivalent', factor: 1 },
};

const concentrationUnits = {
  'g/mL': 'g',
  'mg/mL': 'mg',
  'mcg/mL': 'mcg',
  'U/mL': 'U',
  'mU/mL': 'mU',
  'mEq/mL': 'mEq',
};

const doseUnits = {
  'g/kg/dose': { amount: 'g', period: 'dose' },
  'mg/kg/dose': { amount: 'mg', period: 'dose' },
  'mcg/kg/dose': { amount: 'mcg', period: 'dose' },
  'U/kg/dose': { amount: 'U', period: 'dose' },
  'mU/kg/dose': { amount: 'mU', period: 'dose' },
  'mEq/kg/dose': { amount: 'mEq', period: 'dose' },
  'g/kg/day': { amount: 'g', period: 'day' },
  'mg/kg/day': { amount: 'mg', period: 'day' },
  'mcg/kg/day': { amount: 'mcg', period: 'day' },
  'U/kg/day': { amount: 'U', period: 'day' },
  'mU/kg/day': { amount: 'mU', period: 'day' },
  'mEq/kg/day': { amount: 'mEq', period: 'day' },
};

const infusionUnits = {
  'g/kg/min': { amount: 'g', period: 60 },
  'g/kg/h': { amount: 'g', period: 1 },
  'mg/kg/min': { amount: 'mg', period: 60 },
  'mg/kg/h': { amount: 'mg', period: 1 },
  'mcg/kg/min': { amount: 'mcg', period: 60 },
  'mcg/kg/h': { amount: 'mcg', period: 1 },
  'U/kg/min': { amount: 'U', period: 60 },
  'U/kg/h': { amount: 'U', period: 1 },
  'mU/kg/min': { amount: 'mU', period: 60 },
  'mU/kg/h': { amount: 'mU', period: 1 },
  'mEq/kg/min': { amount: 'mEq', period: 60 },
  'mEq/kg/h': { amount: 'mEq', period: 1 },
};

function positive(value, name) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) {
    throw new Error(`${name} deve ser um número maior que zero.`);
  }
  return number;
}

function matchingUnits(amountUnit, concentrationUnit) {
  const concentrationAmount = concentrationUnits[concentrationUnit];
  if (
    !amountUnits[amountUnit] ||
    !amountUnits[concentrationAmount] ||
    amountUnits[amountUnit].dimension !== amountUnits[concentrationAmount].dimension
  ) {
    throw new Error('As unidades da dose e da concentração não correspondem.');
  }
}

export function calculateDose({
  weightKg,
  dose,
  doseUnit,
  concentration,
  concentrationUnit,
  dosesPerDay = 1,
  maximum,
  maximumScope = 'dose',
}) {
  const weight = positive(weightKg, 'Peso');
  const prescribed = positive(dose, 'Dose');
  const solutionConcentration = positive(concentration, 'Concentração');
  const unit = doseUnits[doseUnit];
  if (!unit || !concentrationUnits[concentrationUnit]) {
    throw new Error('Selecione unidades reconhecidas para dose e concentração.');
  }
  matchingUnits(unit.amount, concentrationUnit);

  const frequency = unit.period === 'day' ? positive(dosesPerDay, 'Doses por dia') : 1;
  if (!Number.isInteger(frequency) || frequency > 24) {
    throw new Error('Doses por dia deve ser um número inteiro entre 1 e 24.');
  }
  if (!['dose', 'day'].includes(maximumScope)) {
    throw new Error('Selecione se o limite máximo é por dose ou por dia.');
  }

  const amountUnit = amountUnits[unit.amount];
  const concentrationAmountUnit = concentrationUnits[concentrationUnit];
  const prescribedAmount = prescribed * weight;
  let totalPerDay = unit.period === 'day' ? prescribedAmount : prescribedAmount * frequency;
  let totalPerDose = totalPerDay / frequency;
  let capped = false;

  if (maximum !== '' && maximum !== undefined && maximum !== null) {
    const maximumAmount = positive(maximum, 'Limite máximo');
    const cap = maximumAmount * amountUnit.factor;
    if (maximumScope === 'day' && totalPerDay * amountUnit.factor > cap) {
      totalPerDay = maximumAmount;
      totalPerDose = totalPerDay / frequency;
      capped = true;
    } else if (maximumScope === 'dose' && totalPerDose * amountUnit.factor > cap) {
      totalPerDose = maximumAmount;
      totalPerDay = totalPerDose * frequency;
      capped = true;
    }
  }

  const finalConcentration = solutionConcentration * amountUnits[concentrationAmountUnit].factor;
  const volumePerDoseMl = (totalPerDose * amountUnit.factor) / finalConcentration;
  const reconstructedPerKgPerDose = (volumePerDoseMl * finalConcentration) /
    amountUnit.factor / weight;
  const reconstructedPerKg = unit.period === 'day'
    ? reconstructedPerKgPerDose * frequency
    : reconstructedPerKgPerDose;
  if (![totalPerDose, totalPerDay, volumePerDoseMl, reconstructedPerKg]
    .every((value) => Number.isFinite(value) && value > 0)) {
    throw new Error('O resultado excede o intervalo numérico; revise os valores informados.');
  }
  const amountLabel = unit.amount;

  return {
    capped,
    dosePerAdministration: totalPerDose,
    dosePerDay: totalPerDay,
    amountUnit: unit.amount,
    doseUnit: `${amountLabel}/kg/${unit.period}`,
    frequency,
    reconstructedPerKg,
    volumePerDoseMl,
  };
}

export function calculateInfusion({
  weightKg,
  dose,
  doseUnit,
  quantity,
  quantityUnit,
  finalVolumeMl,
}) {
  const weight = positive(weightKg, 'Peso');
  const prescribed = positive(dose, 'Dose');
  const medicationQuantity = positive(quantity, 'Quantidade do medicamento');
  const finalVolume = positive(finalVolumeMl, 'Volume final');
  const unit = infusionUnits[doseUnit];
  if (!unit || !amountUnits[quantityUnit]) {
    throw new Error('Selecione unidades reconhecidas para dose e quantidade.');
  }
  if (amountUnits[unit.amount].dimension !== amountUnits[quantityUnit].dimension) {
    throw new Error('As unidades da dose e da quantidade preparada não correspondem.');
  }

  const factor = amountUnits[unit.amount].factor;
  const amountPerKgPerHour = prescribed * factor * unit.period;
  const amountPerHour = amountPerKgPerHour * weight;
  const concentrationPerMl = (medicationQuantity * amountUnits[quantityUnit].factor) / finalVolume;
  const pumpRateMlPerHour = amountPerHour / concentrationPerMl;
  const reconstructedPerKg = pumpRateMlPerHour * concentrationPerMl /
    weight / factor / unit.period;
  if (![amountPerHour, concentrationPerMl, pumpRateMlPerHour, reconstructedPerKg]
    .every((value) => Number.isFinite(value) && value > 0)) {
    throw new Error('O resultado excede o intervalo numérico; revise os valores informados.');
  }

  return {
    amountUnit: unit.amount,
    amountPerHour: amountPerHour / factor,
    amountPerMinute: amountPerHour / factor / 60,
    concentration: medicationQuantity / finalVolume,
    concentrationUnit: `${quantityUnit}/mL`,
    doseUnit,
    pumpRateMlPerHour,
    reconstructedPerKg,
    solutionDurationHours: finalVolume / pumpRateMlPerHour,
    volumeFor6HoursMl: pumpRateMlPerHour * 6,
    volumeFor12HoursMl: pumpRateMlPerHour * 12,
    volumeFor24HoursMl: pumpRateMlPerHour * 24,
  };
}

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172d35;
  background: #f2f6f7;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body { margin: 0; }

.site-header {
  padding: 2.5rem max(1.25rem, calc((100% - 1120px) / 2));
  color: white;
  background: #123d50;
}

.site-header h1 { margin: 0.25rem 0; font-size: clamp(1.8rem, 5vw, 2.8rem); }
.site-header p { margin: 0.5rem 0 0; }
.eyebrow { color: #b9e4dc; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
main { max-width: 1120px; margin: 1.5rem auto; padding: 0 1rem; }

.notice, .panel, .method {
  border: 1px solid #cfdbde;
  border-radius: 0.75rem;
  background: white;
  padding: 1.25rem;
}

.notice { border-left: 6px solid #ad4d00; }
.notice h2 { color: #813900; }
.notice p:last-child, .method p:last-child { margin-bottom: 0; }
.calculators { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; margin: 1rem 0; }
.panel h2, .method h2 { margin-top: 0; }
form { display: grid; gap: 0.85rem; }
label { display: grid; gap: 0.35rem; font-weight: 650; }
input, select, button { min-height: 2.75rem; border: 1px solid #80949a; border-radius: 0.35rem; padding: 0.5rem 0.65rem; font: inherit; }
input:focus, select:focus, button:focus-visible { outline: 3px solid #70b6a8; outline-offset: 2px; }
fieldset { display: grid; gap: 0.8rem; border: 1px solid #cfdbde; border-radius: 0.4rem; padding: 0.9rem; }
legend { font-weight: 700; padding: 0 0.25rem; }
button { border: 0; color: white; background: #145b65; font-weight: 700; cursor: pointer; }
button:hover { background: #0e434b; }
.result { border-radius: 0.4rem; background: #e9f5f1; padding: 0.8rem; overflow-wrap: anywhere; }
.result p:first-child { margin-top: 0; }
.result p:last-child { margin-bottom: 0; }
.warning, .error { color: #813900; font-weight: 700; }
.error { padding: 0.75rem; border-radius: 0.4rem; background: #fff0df; }
.method { margin-bottom: 1rem; }
footer { padding: 1.25rem; text-align: center; color: #42585f; }

@media (max-width: 760px) {
  .calculators { grid-template-columns: 1fr; }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { calculateDose, calculateInfusion } from '../src/calculations.mjs';

test('dose calculation converts mass units and reconstructs the prescribed dose', () => {
  const result = calculateDose({
    weightKg: '10',
    dose: '5',
    doseUnit: 'mg/kg/dose',
    concentration: '1000',
    concentrationUnit: 'mcg/mL',
  });

  assert.equal(result.dosePerAdministration, 50);
  assert.equal(result.volumePerDoseMl, 50);
  assert.equal(result.reconstructedPerKg, 5);
});

test('daily dose is divided by frequency and applies an absolute per-dose cap', () => {
  const result = calculateDose({
    weightKg: 20,
    dose: 10,
    doseUnit: 'mg/kg/day',
    dosesPerDay: 4,
    concentration: 50,
    concentrationUnit: 'mg/mL',
    maximum: 30,
    maximumScope: 'dose',
  });

  assert.equal(result.capped, true);
  assert.equal(result.dosePerAdministration, 30);
  assert.equal(result.dosePerDay, 120);
  assert.equal(result.volumePerDoseMl, 0.6);
  assert.equal(result.reconstructedPerKg, 6);
});

test('infusion conversion calculates mL/h and reconstructs mcg/kg/min', () => {
  const result = calculateInfusion({
    weightKg: 10,
    dose: 5,
    doseUnit: 'mcg/kg/min',
    quantity: 4,
    quantityUnit: 'mg',
    finalVolumeMl: 50,
  });

  assert.equal(result.concentration, 0.08);
  assert.equal(result.concentrationUnit, 'mg/mL');
  assert.equal(result.amountUnit, 'mcg');
  assert.equal(result.amountPerHour, 3000);
  assert.equal(result.pumpRateMlPerHour, 37.5);
  assert.equal(result.reconstructedPerKg, 5);
  assert.equal(result.volumeFor6HoursMl, 225);
});

test('rejects results outside the finite numeric range', () => {
  assert.throws(() => calculateDose({
    weightKg: 1e308,
    dose: 10,
    doseUnit: 'mg/kg/dose',
    concentration: 1,
    concentrationUnit: 'mg/mL',
  }), /intervalo numérico/);
});

test('rejects incompatible units instead of silently converting dimensions', () => {
  assert.throws(() => calculateInfusion({
    weightKg: 5,
    dose: 1,
    doseUnit: 'mcg/kg/min',
    quantity: 1,
    quantityUnit: 'U',
    finalVolumeMl: 10,
  }), /não correspondem/);
});

test('rejects invalid frequency and non-positive values', () => {
  assert.throws(() => calculateDose({
    weightKg: 5,
    dose: 1,
    doseUnit: 'mg/kg/day',
    dosesPerDay: 2.5,
    concentration: 1,
    concentrationUnit: 'mg/mL',
  }), /inteiro entre 1 e 24/);
  assert.throws(() => calculateDose({
    weightKg: 0,
    dose: 1,
    doseUnit: 'mg/kg/dose',
    concentration: 1,
    concentrationUnit: 'mg/mL',
  }), /maior que zero/);
});
